/**
 * @file Access to the generated renderer gamedata (src/gamedata.js) from the main process.
 */
'use strict';

const fs = require('fs');
const path = require('path');

// src/gamedata.js is generated by scripts/gen-gamedata.py as a plain browser script (`const GAMEDATA = {...};`) and parsed as JSON by tools/tests,
// so it has no module export: evaluate it the same way the tests do. Read on every call (the file is small), exactly as main.js always did.
/**
 * Return the generated game data (skills, weapons, classes, missions, boosters), or {} when it cannot be read.
 * @returns {object}
 */
function gameData() {
  try {
    return new Function(
      fs.readFileSync(path.join(__dirname, '..', 'src', 'gamedata.js'), 'utf8') +
        '\nreturn GAMEDATA;',
    )();
  } catch {
    return {};
  }
}

module.exports = gameData;
